import 'package:material_ui/material_ui.dart';

import 'package:waylight_mobile/l10n/generated/app_localizations.dart';

export 'package:waylight_mobile/l10n/generated/app_localizations.dart';

/// The delegates for `MaterialApp.localizationsDelegates`.
///
/// Not `AppLocalizations.localizationsDelegates`: the code generated by
/// `flutter gen-l10n` still names the Material localizations of the
/// framework, while the widgets come from `package:material_ui` since
/// Flutter 3.50 and look for its own type (docs/adr/0002-flutter-stack.md).
const List<LocalizationsDelegate<Object?>> appLocalizationsDelegates = [
  AppLocalizations.delegate,
  ...GlobalMaterialLocalizations.delegates,
];

/// Short access to the translated texts: `context.l10n.connectButton`.
extension AppLocalizationsX on BuildContext {
  /// The texts in the language of the device.
  AppLocalizations get l10n => AppLocalizations.of(this);
}
